// Genereras av kallor-kemi/omrade1/exportsite.py (sajtkonv.py, latt_ov.py) – ändra inte för hand.
// Kemi område 1: varje moment i tre nivåer (lättläst, grundtext, fördjupning), skrivet för skärm i sajtens vanliga sidformat. Elevversion, utan facit. Lättläst har interaktiva övningar.
var innehall = window.innehall || {};
innehall["kemi-m-1-1-1"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Vad är kemi?", "text": ["<p><strong>Kemi</strong> handlar om ämnen och hur de förändras. Allt du ser och rör vid är gjort av ämnen: vatten, socker, plast och luft.</p>", "<p>Kemi är en <strong>naturvetenskap</strong>. Kemister gissar inte. De gör undersökningar och mäter.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/l_kemister.png\" alt=\"\"></figure>", "<p>Det finns många sorters kemister. De kan till exempel mäta vad ett prov innehåller, ta fram läkemedel, utveckla nya material eller undersöka föroreningar.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Kemi är läran om ämnen och hur de förändras. Kemister undersöker och mäter.</div>"]}, {"ikon": "✏️", "titel": "Öva: Vad är kemi?", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad handlar kemi om?", "val": ["Ämnen och hur de förändras", "Bara om djur", "Bara om planeter"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Kemister gör undersökningar och mäter.", "Kemi finns bara i labbet.", "Vatten är ett ämne."], "ratt": [true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["förändras", "mäter", "ämnen"], "meningar": ["Kemi handlar om §.", "Ämnen § i kemiska reaktioner.", "En kemist § och undersöker."], "ratt": ["ämnen", "förändras", "mäter"]}, {"typ": "skriv", "fraga": "Nämn något i ditt kök som är gjort av kemiska ämnen.", "borja": "Ett exempel är", "forslag": "Till exempel socker, salt, vatten eller diskmedel."}]}, {"ikon": "🧪", "titel": "Säkerhet och utrustning i kemilabbet", "text": ["<p>I ett kemilabb är säkerheten viktigast.</p>", "<ol><li>Ha skyddsglasögon på.</li><li>Sätt upp långt hår.</li><li>Smaka eller drick aldrig något.</li><li>Ät inte i labbet.</li><li>Torka upp spill och säg till läraren.</li><li>Tvätta händerna efteråt.</li></ol>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_utrustning.png\" alt=\"\"></figure>", "<p>Farliga produkter har <strong>faropiktogram</strong>. Det är röda rutor med en svart bild.</p>", "<p>På etiketten står också <strong>Fara</strong> eller <strong>Varning</strong>.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_piktogram.png\" alt=\"\"></figure>", "<p>Du mäter volym med en <strong>mätcylinder</strong>. Håll ögonen i höjd med vattenytan. Läs av där ytan är lägst.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Använd skyddsglasögon. Smaka aldrig. Läs av mätcylindern med ögonen i höjd med ytan.</div>"]}, {"ikon": "✏️", "titel": "Öva: Säkerhet och utrustning i kemilabbet", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad ska du alltid ha på dig när du arbetar med kemikalier?", "val": ["Skyddsglasögon", "Mössa", "Handskar av ull"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Du får smaka på ämnen i labbet.", "Långt hår ska sättas upp.", "Piktogrammen visar vilken fara ämnet har."], "ratt": [false, true, true]}, {"typ": "streck", "fraga": "Dra streck till rätt mätning.", "vanster": ["Volym", "Massa", "Temperatur"], "hoger": ["mätcylinder", "termometer", "våg"], "ratt": ["mätcylinder", "våg", "termometer"]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["faropiktogram", "skyddsglasögon", "ytan"], "meningar": ["Jag har § på mig i labbet.", "Ett § visar vilken fara ett ämne har.", "Jag läser av vid den lägsta delen av §."], "ratt": ["skyddsglasögon", "faropiktogram", "ytan"]}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Vad är kemi?", "text": ["<p><strong>Kemi</strong> är läran om ämnen och hur de förändras. Allt du ser, äter och rör vid är gjort av kemiska ämnen: vatten, socker, plast, tvål, luft. När en brustablett löser sig, när järn rostar eller när mat tillagas sker kemiska förändringar. Kemi är därför inte något som bara finns i ett labb.</p>", "<p>Kemi är också en <strong>naturvetenskap</strong>. Det betyder att kemister inte nöjer sig med att tro eller gissa. De ställer frågor, gör undersökningar, mäter och prövar sina förklaringar mot det som verkligen händer. Andra kemister kontrollerar och upprepar försöken. Det är det som gör att vi kan lita på kunskapen.</p>", "<p>Det finns många slags kemister. Några exempel är <strong>analytiska kemister</strong> som mäter vad ett prov innehåller, <strong>läkemedelskemister</strong> som tar fram och testar läkemedel, <strong>materialkemister</strong> som utvecklar material som plast och batterier och <strong>miljökemister</strong> som undersöker föroreningar i luft, vatten och mark.</p>", "<p>I det här kapitlet svarar vi på tre frågor:</p>", "<ul><li>Hur arbetar en kemist säkert, planerar ett rättvist försök och värderar resultatet?</li><li>Vad är en modell, och hur har kemins modeller förändrats?</li><li>Hur granskar du påståenden om kemi, till exempel i reklam?</li></ul>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Nämn tre kemiska förändringar du har sett den här veckan. Hur vet du att det är en förändring och inte bara en blandning?</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Delområde</th><th>Du lär dig</th></tr><tr><td><strong>1.1</strong> Arbeta som kemist</td><td>Säkerhet och utrustning, att gå från fråga till plan och att dokumentera och värdera. Labb: brustabletten och temperaturen.</td></tr><tr><td><strong>1.2</strong> Modeller, källor och argument</td><td>Vad en modell är, hur kemin vuxit fram och hur du granskar påståenden. Labb: fungerar fläckborttagaren?</td></tr></table></div>"], "fragor": [{"f": "Vad handlar kemi om?", "svar": "Om ämnen och hur de förändras, till exempel när något löses upp, rostar, bränns eller blandas."}, {"f": "Nämn tre sorters arbete där man behöver kemi.", "svar": "T.ex. analytisk kemist (mäter vad prov innehåller), läkemedelskemist, materialkemist, miljökemist."}, {"f": "Varför räcker det inte att bara läsa om kemi för att förstå den?", "svar": "Kemi är en naturvetenskap: svaren prövas genom undersökningar och mätningar, inte bara genom att man tror eller läser."}]}, {"ikon": "🧪", "titel": "Säkerhet och utrustning i kemilabbet", "text": ["<p>I ett kemilabb arbetar du med ämnen som kan vara farliga om de hanteras fel. Därför har alla samma grundregler. De skyddar både dig och dem du arbetar med.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_utrustning.png\" alt=\"Bild 1.1 Vanlig utrustning i ett kemilabb: mätcylinder, bägare, E-kolv, provrör, våg, termometer, pipett och skyddsglasögon.\"><figcaption><strong>Bild 1.1</strong> Vanlig utrustning i ett kemilabb: mätcylinder, bägare, E-kolv, provrör, våg, termometer, pipett och skyddsglasögon.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Grundregler", "text": ["<ul><li>Använd <strong>skyddsglasögon</strong> hela tiden när du arbetar med kemikalier eller värme.</li><li>Sätt upp långt hår, ha inga hängande smycken och bär stängda skor.</li><li>Smaka, sniffa och dricka aldrig något i labbet, och ät inte där.</li><li>Läs hela instruktionen innan du börjar och ta bara den mängd du behöver.</li><li>Torka upp spill direkt och berätta för läraren om något går sönder eller spills.</li><li>Tvätta händerna när du är klar.</li><li>Vet du inte vad ett ämne är? Fråga innan du använder det.</li></ul>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför är regeln om skyddsglasögon viktig även när ni bara använder vatten och en brustablett?</div>"]}, {"ikon": "📖", "titel": "Faropiktogram och etiketter", "text": ["<p>Farliga produkter är märkta med <strong>faropiktogram</strong>: röda rutor på spetsen med en svart bild. De visar vilken sorts fara det handlar om. På etiketten finns också ett <strong>signalord</strong>, antingen <em>Fara</em> (för de allvarligaste farorna) eller <em>Varning</em>, och <strong>faroangivelser</strong> som beskriver farorna med ord. Där står också produktens namn och leverantörens kontaktuppgifter.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_piktogram.png\" alt=\"Bild 1.2 De nio faropiktogrammen: explosivt, brandfarligt, oxiderande, gas under tryck, frätande, akut giftigt, hälsofarligt, varning (utropstecken) och miljöfarligt.\"><figcaption><strong>Bild 1.2</strong> De nio faropiktogrammen: explosivt, brandfarligt, oxiderande, gas under tryck, frätande, akut giftigt, hälsofarligt, varning (utropstecken) och miljöfarligt.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Mäta rätt", "text": ["<p>Kemister mäter volym, massa och temperatur. <strong>Volym</strong> mäts i milliliter (ml) med en mätcylinder. Vattnets yta är lite böjd, och den böjda ytan kallas <strong>menisk</strong>. Du håller ögonen i nivå med ytan och läser av vid den lägsta delen. <strong>Massa</strong> mäts i gram (g) med en våg. <strong>Temperatur</strong> mäts i grader Celsius (°C) med en termometer. Låt termometern hänga fritt i vätskan och vänta tills värdet slutat ändras innan du läser av.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_menisk.png\" alt=\"Bild 1.3 Avläsning av en mätcylinder. Håll ögonen i nivå med ytan. Fel avläsning ger fel värde.\"><figcaption><strong>Bild 1.3</strong> Avläsning av en mätcylinder. Håll ögonen i nivå med ytan. Fel avläsning ger fel värde.</figcaption></figure>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Om något går fel</span>Få kemikalier i ögonen: skölj genast med mycket vatten och säg till läraren. Misstänker du att någon fått i sig något farligt: ring <strong>112</strong> och begär Giftinformationscentralen. Vänta inte på symtom. Vid mindre bråttom kan du ringa Giftinformationscentralen på <strong>010-456 67 00</strong>, dygnet runt.</div>"], "fragor": [{"f": "Nämn tre regler du alltid följer i ett kemilabb.", "svar": "T.ex. skyddsglasögon, långt hår uppsatt, aldrig smaka eller dricka, ingen mat i labbet, tvätta händerna, berätta för läraren om något går fel."}, {"f": "Vad betyder en röd ruta med en brinnande låga som faropiktogram?", "svar": "Ämnet är brandfarligt: det kan antändas lätt."}, {"f": "Vad står på en kemikalieetikett förutom produktnamnet?", "svar": "Faropiktogram, signalord (Fara eller Varning), faroangivelser och leverantörens kontaktuppgifter."}, {"f": "Hur läser du av en mätcylinder rätt?", "svar": "Ögonen i nivå med vattenytan, och du läser av vid den lägsta delen av den böjda ytan (menisken)."}, {"f": "Vad gör du om du misstänker att någon fått i sig något farligt?", "svar": "Ring 112 och begär Giftinformationscentralen. Vänta inte på symtom. Vid mindre bråttom: 010-456 67 00."}]}], "begrepp": [{"term": "Kemi", "forklaring": "Läran om ämnen och hur de förändras."}, {"term": "Naturvetenskap", "forklaring": "Kunskap som prövas med undersökningar och mätningar."}, {"term": "Ämne", "forklaring": "En sorts material med bestämda egenskaper, t.ex. vatten eller socker."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-1-1-2"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "❓", "titel": "Från fråga till plan", "text": ["<p>En undersökning börjar med en fråga som du kan mäta svaret på.</p>", "<p><strong>Exempel:</strong> Hur påverkar vattnets temperatur tiden det tar för en brustablett att lösa sig?</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/l_cykel.png\" alt=\"\"></figure>", "<p>En <strong>hypotes</strong> är en gissning som du kan pröva. Skriv: ”Om … så …, eftersom …”.</p>", "<p>I ett försök finns tre sorters <strong>variabler</strong>.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_brus.png\" alt=\"\"></figure>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Variabel</th><th>I försöket</th></tr><tr><td>Jag ändrar</td><td>Vattnets temperatur</td></tr><tr><td>Jag mäter</td><td>Tiden tills tabletten är borta</td></tr><tr><td>Jag håller lika</td><td>Mängd vatten, sort på tablett</td></tr></table></div>", "<p>Ett försök är <strong>rättvist</strong> om du bara ändrar en sak i taget.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Ändra en sak i taget. Mät något. Håll allt annat lika.</div>"]}, {"ikon": "✏️", "titel": "Öva: Från fråga till plan", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad är en hypotes?", "val": ["En gissning som går att pröva", "Ett säkert svar", "En tabell"], "ratt": 0}, {"typ": "streck", "fraga": "Dra streck till rätt sorts variabel.", "vanster": ["Jag ändrar", "Jag mäter", "Jag håller lika"], "hoger": ["mängd vatten", "temperatur", "tid tills tabletten är borta"], "ratt": ["temperatur", "tid tills tabletten är borta", "mängd vatten"]}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["I ett rättvist försök ändrar man bara en sak i taget.", "Man ska ändra både temperatur och vattenmängd.", "En hypotes kan visa sig vara fel."], "ratt": [true, false, true]}, {"typ": "skriv", "fraga": "Du vill veta om en sockerbit löser sig fortare om du rör om. Vad ändrar du?", "borja": "Jag ändrar", "forslag": "Om du rör om eller inte. Allt annat ska vara lika."}]}]}, "vanlig": {"sektioner": [{"ikon": "❓", "titel": "Från fråga till plan", "text": ["<p>En undersökning börjar med en fråga. Inte alla frågor går att undersöka i ett kemilabb. ”Är brustabletter goda?” är en fråga om tycke. ”Hur påverkar vattnets temperatur tiden det tar för en brustablett att lösa sig?” är en <strong>undersökningsbar fråga</strong>: du kan mäta svaret.</p>", "<p>Sedan skriver du en <strong>hypotes</strong>. Det är en gissning som du kan pröva, helst med en förklaring: ”<em>Om vattnet är varmare, så löser tabletten sig fortare, eftersom allt rör sig snabbare i varmt vatten.</em>” En hypotes kan visa sig vara fel. Det är också ett viktigt resultat.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_brus.png\" alt=\"Bild 1.4 Tre glas med brustablett. Samma mängd vatten och samma sorts tablett i alla glas. Det enda som ändras är temperaturen.\"><figcaption><strong>Bild 1.4</strong> Tre glas med brustablett. Samma mängd vatten och samma sorts tablett i alla glas. Det enda som ändras är temperaturen.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Variabler", "text": ["<p>I ett försök finns tre sorters <strong>variabler</strong>. Den <strong>oberoende variabeln</strong> är det du ändrar, här vattnets temperatur. Den <strong>beroende variabeln</strong> är det du mäter för att se om den påverkas, här tiden tills tabletten är upplöst. Alla andra saker som kan påverka resultatet, till exempel vattenmängd, tablettens storlek och sort och hur du startar och stoppar klockan, ska du hålla lika. De kallas <strong>kontrollerade variabler</strong>.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Sorts variabel</th><th>I brustablettförsöket</th></tr><tr><td>Oberoende (jag ändrar)</td><td>Vattnets temperatur: 5 °C, 20 °C och 40 °C</td></tr><tr><td>Beroende (jag mäter)</td><td>Tid tills tabletten är upplöst, i sekunder</td></tr><tr><td>Kontrollerade (jag håller lika)</td><td>Vattenmängd, tablettsort och storlek, glasets form, ingen omrörning, samma sätt att mäta tiden</td></tr></table></div>"]}, {"ikon": "🔎", "titel": "Ett rättvist försök", "text": ["<p>Ett försök är <strong>rättvist</strong> om du bara ändrar en variabel i taget. Ändrar du två saker samtidigt, till exempel både temperatur och vattenmängd, kan du inte veta vilken som gav skillnaden. Ofta behöver du också en <strong>jämförelse</strong>, ett prov där du inte ändrar något, så att du har något att jämföra med.</p>", "<p>Skriv sedan en <strong>plan</strong> innan du börjar: vilken utrustning du behöver, vad du gör i vilken ordning, hur du mäter och hur många gånger du upprepar. Gör också en tom tabell att fylla i.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Du vill veta om en sockerbit löser sig fortare om du rör om. Vilken variabel ändrar du, vilken mäter du och vad håller du lika?</div>"], "fragor": [{"f": "Vad är en hypotes?", "svar": "En välgrundad gissning som går att pröva i en undersökning, ofta på formen ”om … så …, eftersom …”."}, {"f": "Vad är skillnaden mellan den oberoende och den beroende variabeln?", "svar": "Den oberoende variabeln ändrar du. Den beroende mäter du för att se om den påverkas."}, {"f": "Varför ska bara en variabel ändras i taget?", "svar": "Annars vet du inte vad som orsakade skillnaden i resultatet."}, {"f": "Ge två exempel på kontrollerade variabler i brustablettförsöket.", "svar": "T.ex. vattenmängd, tablettens storlek och sort, glasets form, att alla startar och stoppar klockan på samma sätt."}]}], "begrepp": [{"term": "Hypotes", "forklaring": "En gissning som går att pröva."}, {"term": "Undersökningsbar fråga", "forklaring": "En fråga som går att svara på med mätningar."}, {"term": "Variabel", "forklaring": "Något som kan ändras eller mätas i ett försök."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-1-1-3"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📊", "titel": "Dokumentera och värdera", "text": ["<p>Skriv ner dina mätvärden i en tabell. Skriv enheter, till exempel s för sekunder.</p>", "<p>Gör flera mätningar. Räkna sedan ut <strong>medelvärdet</strong>.</p>", "<p><strong>Exempel:</strong> 70 s, 78 s och 74 s. Medelvärdet är (70 + 78 + 74) / 3 = 74 s.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_brusdiagram.png\" alt=\"\"></figure>", "<p>Ett diagram visar mönster. Det du ändrar (temperatur) ligger på den vågräta axeln. Det du mäter (tid) ligger på den lodräta.</p>", "<p>En <strong>felkälla</strong> är något som kan göra mätningen osäker, till exempel att klockan startas sent.</p>", "<p>En <strong>slutsats</strong> svarar på frågan: Ju varmare vatten, desto kortare tid. Hypotesen stämde.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Upprepa mätningarna, räkna medelvärde och skriv en slutsats som svarar på frågan.</div>"]}, {"ikon": "✏️", "titel": "Öva: Dokumentera och värdera", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Hur räknar du ut ett medelvärde?", "val": ["Lägger ihop värdena och delar med antalet", "Tar det största värdet", "Tar det minsta värdet"], "ratt": 0}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["felkälla", "medelvärdet", "slutsats"], "meningar": ["Jag räknade ut §.", "Att klockan startade sent är en §.", "Jag skrev en § som svarar på frågan."], "ratt": ["medelvärdet", "felkälla", "slutsats"]}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Ett tal behöver en enhet.", "Man ska bara göra en mätning.", "Man ska upprepa mätningarna."], "ratt": [true, false, true]}, {"typ": "skriv", "fraga": "Räkna ut medelvärdet av 29 s, 33 s och 31 s.", "borja": "Medelvärdet är", "forslag": "(29 + 33 + 31) ÷ 3 = 93 ÷ 3 = 31 s."}]}]}, "vanlig": {"sektioner": [{"ikon": "📊", "titel": "Dokumentera och värdera", "text": ["<p>Skriv ner det du mäter medan du mäter, inte efteråt. Använd en <strong>tabell</strong> med rubriker och <strong>enheter</strong> (till exempel s för sekunder och °C för grader Celsius). Ett tal utan enhet säger nästan ingenting.</p>", "<p>Gör alltid flera mätningar för samma sak. Då ser du hur mycket värdena varierar, och slumpen får mindre makt över resultatet. För varje temperatur räknar du ut <strong>medelvärdet</strong>: lägg ihop alla värden och dela med antalet. Av 70 s, 78 s och 74 s blir medelvärdet (70 + 78 + 74) / 3 = 74 s.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_brusdiagram.png\" alt=\"Bild 1.5 Medelvärden från ett exempelförsök med brustablett. Mätvärdena är påhittade.\"><figcaption><strong>Bild 1.5</strong> Medelvärden från ett exempelförsök med brustablett. Mätvärdena är påhittade.</figcaption></figure>", "<p>Ett <strong>diagram</strong> gör mönster lättare att se. Lägg det du ändrar (temperaturen) på den vågräta axeln och det du mäter (tiden) på den lodräta. Skriv ut namn och enhet på båda axlarna och sätt en rubrik.</p>"]}, {"ikon": "✅", "titel": "Värdera resultatet", "text": ["<p>Fråga dig: Svarar resultatet på frågan? Stämde hypotesen? Vilka <strong>felkällor</strong> kan ha påverkat? Det kan vara att klockan startades sent, att termometern lästes av fel eller att vattnet hann svalna. Skriv hur du skulle göra annorlunda nästa gång.</p>", "<p>Slutsatsen ska bygga på dina egna mätningar. Skriv den som ett svar på frågan: ”<em>Ju varmare vatten, desto kortare tid tog det för tabletten att lösa sig. Hypotesen stämde.</em>” Skriv också hur säker du är. Hade du få mätningar eller stora skillnader mellan försöken är du mindre säker. Om ett värde sticker ut kan du undersöka om det beror på ett misstag, men du får inte bara ta bort det för att det inte passar.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Tre grupper mäter 148 s, 160 s och 148 s för samma temperatur. Är värdena lika nog för att lita på medelvärdet? Varför?</div>"], "fragor": [{"f": "Varför ska man upprepa mätningarna?", "svar": "För att se hur mycket värdena varierar och för att minska risken att ett slumpfel avgör resultatet."}, {"f": "Räkna ut medelvärdet av 70 s, 78 s och 74 s.", "svar": "(70 + 78 + 74) / 3 = 74 s."}, {"f": "Vad är en felkälla? Ge ett exempel.", "svar": "Något som kan göra mätningen mindre säker, t.ex. att man startar klockan sent, läser av termometern fel eller att vattnet svalnar."}, {"f": "Vad ska en slutsats innehålla?", "svar": "Ett svar på frågeställningen som bygger på resultatet, och om hypotesen stämde."}]}], "begrepp": [{"term": "Felkälla", "forklaring": "Något som kan göra en mätning mindre säker."}, {"term": "Medelvärde", "forklaring": "Summan av värdena delat med antalet värden."}, {"term": "Slutsats", "forklaring": "Svaret på frågan, byggt på resultatet."}]}, "fordjupning": {"sektioner": [{"ikon": "📊", "titel": "Dokumentera och värdera", "text": ["<p>I grundtexten lärde du dig att upprepa mätningar och räkna medelvärde. Här tittar vi på <em>varför</em> det hjälper, och på vad som händer när mätningarna inte blir bra ändå. Ett mätvärde kan vara dåligt på två sätt som är olika.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/f_traff.png\" alt=\"Bild F1.1 Fyra mätserier som träffar en tavla. Mitten är det sanna värdet. Precision handlar om spridningen, riktighet om hur nära medelvärdet ligger det sanna värdet.\"><figcaption><strong>Bild F1.1</strong> Fyra mätserier som träffar en tavla. Mitten är det sanna värdet. Precision handlar om spridningen, riktighet om hur nära medelvärdet ligger det sanna värdet.</figcaption></figure>", "<p><strong>Precision</strong> säger hur nära varandra upprepade mätningar ligger. Är värdena lika har mätningen hög precision. Spridningen beror ofta på <strong>slumpfel</strong>: små, oförutsägbara skillnader som att du startar klockan lite för tidigt ena gången och lite för sent nästa. Slumpfel går åt båda hållen, och därför minskar de när du tar medelvärde av flera mätningar.</p>", "<p><strong>Riktighet</strong> säger hur nära det sanna värdet mätningarna ligger. En termometer som visar två grader för högt ger lika fel värde varje gång. Det är ett <strong>systematiskt fel</strong>: det går åt samma håll hela tiden. Systematiska fel syns inte som spridning, och medelvärde hjälper inte. Det kan finnas hög precision men låg riktighet.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Du läser alltid av mätcylindern med ögonen från samma felaktiga håll. Är det ett slumpfel eller ett systematiskt fel? Hjälper det att upprepa mätningen?</div>"]}, {"ikon": "📖", "titel": "Vad gör man åt det?", "text": ["<p>Slumpfel minskar du genom att upprepa mätningarna och räkna medelvärde, och genom att göra mätningen lika varje gång. Systematiska fel minskar du genom att kontrollera utrustningen, till exempel jämföra termometern med en annan, och genom att ha en <strong>jämförelse</strong> som utsätts för samma fel. Har båda proverna samma systematiska fel påverkar det inte skillnaden mellan dem, vilket är ett skäl till att jämförelser är så starka.</p>", "<p>Ibland sticker ett mätvärde ut. Det kan vara ett misstag, men det kan också vara något intressant. Frågan är hur man hanterar det på ett hederligt sätt.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/f_punkter.png\" alt=\"Bild F1.2 Tre försök för tre temperaturer i klass 8B (påhittade värden). Strecken visar medelvärdet. Vid 20 °C sticker ett värde ut.\"><figcaption><strong>Bild F1.2</strong> Tre försök för tre temperaturer i klass 8B (påhittade värden). Strecken visar medelvärdet. Vid 20 °C sticker ett värde ut.</figcaption></figure>", "<p>Vid 20 °C blev klassens tre mätningar 70 s, 118 s och 72 s. Medelvärdet med alla tre är 87 s. Utan det avvikande värdet blir medelvärdet 71 s. Skillnaden är stor, så beslutet spelar roll. Man får <em>inte</em> bara ta bort ett värde för att det inte passar. Man gör så här:</p>", "<ol><li>Kolla anteckningarna: finns det en känd orsak, till exempel att klockan stoppades sent eller att tabletten fastnade vid glaset?</li><li>Gör om mätningen om det går. Finns det då inget skäl att misstänka ett misstag, behåll värdet.</li><li>Redovisa öppet vad du gjort. Skriv både medelvärdet med och utan värdet, och vilken motivering du har.</li><li>Överväg ett mått som tål avvikelser: <strong>medianen</strong> är mittersta värdet när värdena ordnas (här 72 s).</li></ol>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför är det oärligt att ta bort ett värde bara för att det förstör mönstret? När kan det vara rätt att ta bort ett värde?</div>"]}, {"ikon": "✅", "titel": "Hur säker är slutsatsen?", "text": ["<p>Tre försök vid 5 °C gav 150 s, 160 s och 148 s, och vid 40 °C gav de 29 s, 33 s och 31 s. Spridningen inom varje grupp är liten jämfört med skillnaden <em>mellan</em> grupperna. Det talar för att temperaturen verkligen påverkar tiden. Vid 20 °C är spridningen stor, så där är kunskapen mer osäker. En bra slutsats säger både vad resultatet visar och hur säker man är: ”Tiden minskar när temperaturen ökar. Vid 20 °C är vi mer osäkra eftersom ett försök avvek.”</p>", "<p>Var också försiktig med att dra slutsatser <em>utanför</em> det du mätt. Du har mätt vid 5, 20 och 40 °C. Du vet inte säkert vad som händer vid 80 °C. Mellan mätpunkterna kan du uppskatta, men en uppskattning är inte en mätning.</p>", "<p><strong>Förklaringsmodell.</strong> Resultatet kan förklaras med partikelmodellen: när vattnet är varmare rör sig partiklarna snabbare, så de träffar tabletten oftare och med mer energi, och reaktionen går fortare. Förklaringen är en modell, inte något vi har sett direkt i just det här försöket. Din mätning visar <em>att</em> det går fortare. Modellen föreslår <em>varför</em>.</p>"]}], "begrepp": [{"term": "Avvikande värde", "forklaring": "Ett mätvärde som ligger långt från de andra."}, {"term": "Median", "forklaring": "Det mittersta värdet när värdena ordnas i storleksordning."}, {"term": "Precision", "forklaring": "Hur nära varandra upprepade mätningar ligger."}, {"term": "Riktighet", "forklaring": "Hur nära det sanna värdet mätningarna ligger."}, {"term": "Slumpfel", "forklaring": "Oförutsägbara fel som går åt båda hållen."}, {"term": "Systematiskt fel", "forklaring": "Fel som går åt samma håll varje gång."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-1-1-l"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧪", "titel": "Labb 1.1 Brustabletten och temperaturen", "text": ["<p><strong>Fråga:</strong> Hur påverkar vattnets temperatur tiden det tar för en brustablett att lösa sig?</p>", "<p>Du behöver: tre glas, mätcylinder, termometer, ur, brustabletter, vatten, skyddsglasögon.</p>", "<ol><li>Mät upp 2 dl vatten i varje glas.</li><li>Gör vattnet cirka 5 °C, 20 °C och 40 °C.</li><li>Släpp ner en tablett och starta klockan.</li><li>Stoppa klockan när tabletten är borta.</li><li>Gör tre försök för varje temperatur.</li><li>Räkna medelvärde.</li></ol>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Temperatur</th><th>Försök 1 (s)</th><th>Försök 2 (s)</th><th>Försök 3 (s)</th><th>Medelvärde (s)</th></tr><tr><td>5 °C</td><td></td><td></td><td></td><td></td></tr><tr><td>20 °C</td><td></td><td></td><td></td><td></td></tr><tr><td>40 °C</td><td></td><td></td><td></td><td></td></tr></table></div>", "<p><strong>Säkerhet:</strong> Ha skyddsglasögon. Drick inte vattnet. Använd inte varmare vatten än 40 °C. Torka upp spill.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Rör inte om. Starta och stoppa klockan på samma sätt varje gång.</div>"]}, {"ikon": "✏️", "titel": "Öva: Labb 1.1 Brustabletten och temperaturen", "text": [], "ovningar": [{"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["mängd vatten", "temperaturen", "tiden"], "meningar": ["Jag ändrade §.", "Jag mätte §.", "Jag höll lika §."], "ratt": ["temperaturen", "tiden", "mängd vatten"]}, {"typ": "skriv", "fraga": "Vad visar ditt resultat? Stämde din hypotes?", "borja": "Mitt resultat visar", "forslag": "Egna resultat, till exempel att tabletten löste sig fortare i varmare vatten."}, {"typ": "skriv", "fraga": "Vad kan ha gjort mätningen osäker?", "borja": "Det kan ha varit", "forslag": "Till exempel att klockan startades sent eller att vattnet svalnade."}]}]}, "vanlig": {"sektioner": [{"ikon": "🧪", "titel": "Labb 1.1 Brustabletten och temperaturen", "text": ["<p>Du ska undersöka hur vattnets temperatur påverkar hur fort en brustablett löser sig, och följa hela vägen från fråga till slutsats.</p>", "<p><strong>Frågeställning:</strong> Hur påverkar vattnets temperatur tiden det tar för en brustablett att lösa sig?</p>", "<p><strong>Hypotes:</strong> Skriv din hypotes med ”om … så …, eftersom …”.</p>", "<p><strong>Material:</strong> tre genomskinliga glas (samma sort), mätcylinder, termometer, ur eller stoppur, brustabletter av samma sort (minst nio), kallt vatten med is, kranvatten och varmt vatten, skyddsglasögon.</p>"]}, {"ikon": "📖", "titel": "Gör så här", "text": ["<ol><li>Mät upp samma mängd vatten i varje glas, till exempel 2 dl (200 ml).</li><li>Gör vattnet cirka 5 °C, 20 °C och 40 °C. Kontrollera med termometern. Använd inte varmare vatten än 40 °C.</li><li>Släpp ner en hel tablett i det första glaset och starta klockan i samma stund. Rör inte om.</li><li>Stoppa klockan när tabletten har försvunnit helt. Skriv tiden i tabellen.</li><li>Upprepa med nytt vatten, tre försök för varje temperatur.</li><li>Räkna ut medelvärdet för varje temperatur och rita ett stapeldiagram.</li></ol>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Bra att veta</span>Brustabletten innehåller bland annat citronsyra och natriumvätekarbonat. När de kommer i vatten reagerar de med varandra och bildar koldioxidgas. Det är bubblorna du ser.</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Temperatur</th><th>Försök 1 (s)</th><th>Försök 2 (s)</th><th>Försök 3 (s)</th><th>Medelvärde (s)</th></tr><tr><td>5 °C</td><td></td><td></td><td></td><td></td></tr><tr><td>20 °C</td><td></td><td></td><td></td><td></td></tr><tr><td>40 °C</td><td></td><td></td><td></td><td></td></tr></table></div>"]}, {"ikon": "❓", "titel": "Frågor", "text": ["<ol><li>Vilken variabel ändrade du, vilken mätte du och vad höll du lika?</li><li>Vad visar ditt diagram? Stämde din hypotes?</li><li>Förklara resultatet. Hur kan det hänga ihop med att partiklarna rör sig snabbare i varmt vatten?</li><li>Vilka felkällor kan ha påverkat resultatet, och hur skulle du minska dem?</li><li>Hur kan du göra försöket säkrare att lita på?</li></ol>", "<p class=\"not\">Säkerhet: Använd skyddsglasögon. Drick inte av vattnet eller tabletterna. Använd inte varmare vatten än 40 °C. Torka upp spill direkt.</p>"]}], "begrepp": [{"term": "Beroende variabel", "forklaring": "Det du mäter."}, {"term": "Medelvärde", "forklaring": "Summan delat med antalet."}, {"term": "Oberoende variabel", "forklaring": "Det du ändrar."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-1-2-1"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧩", "titel": "Vad är en modell i kemi?", "text": ["<p>Kemister arbetar med sådant som är för litet att se. Då använder de <strong>modeller</strong>.</p>", "<p>En modell är en enkel bild eller idé som förklarar något. En modell är inte riktiga verkligheten.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/l_modell.png\" alt=\"\"></figure>", "<p><strong>Exempel:</strong> I partikelmodellen tänker vi oss att ämnen består av små partiklar.</p>", "<p>Modellen förklarar varför en brustablett löser sig fortare i varmt vatten: partiklarna rör sig snabbare.</p>", "<p>Men modellen kan inte förklara allt, till exempel ämnets färg. Då behövs en annan modell.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>En modell är en förenkling. Den kan förklara en del men inte allt.</div>"]}, {"ikon": "✏️", "titel": "Öva: Vad är en modell i kemi?", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad är en modell?", "val": ["En enkel bild eller idé som förklarar något", "En riktig bit av ett ämne", "En tabell med mätvärden"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["En modell är samma sak som verkligheten.", "En modell kan förklara en del men inte allt.", "En karta är en modell."], "ratt": [false, true, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["färg", "förenkling", "partiklar"], "meningar": ["En modell är en §.", "I partikelmodellen består ämnen av §.", "Modellen säger inget om ämnets §."], "ratt": ["förenkling", "partiklar", "färg"]}, {"typ": "skriv", "fraga": "Ge ett exempel på en modell du ser i vardagen.", "borja": "Ett exempel är", "forslag": "Till exempel en karta eller en tunnelbanekarta."}]}]}, "vanlig": {"sektioner": [{"ikon": "🧩", "titel": "Vad är en modell i kemi?", "text": ["<p>Kemister arbetar med sådant som är för litet att se. Därför använder de <strong>modeller</strong>. En modell är en förenklad bild eller idé som hjälper oss att förklara och förutsäga hur något fungerar. En modell är inte verkligheten. Den lämnar medvetet bort detaljer, precis som en karta lämnar bort de flesta saker som finns i landskapet.</p>", "<p>Ett exempel är <strong>partikelmodellen</strong>. I den tänker vi oss att ett ämne är uppbyggt av små partiklar. I ett fast ämne sitter de tätt på fasta platser. I en vätska ligger de tätt men kan glida förbi varandra. I en gas är det stora avstånd och partiklarna rör sig fritt. Du lär dig mer om partikelmodellen i kapitel 2.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/l_modell.png\" alt=\"Bild 1.6 Partikelmodellen för fast ämne, vätska och gas. Partiklarna är i verkligheten otroligt mycket mindre än i bilden.\"><figcaption><strong>Bild 1.6</strong> Partikelmodellen för fast ämne, vätska och gas. Partiklarna är i verkligheten otroligt mycket mindre än i bilden.</figcaption></figure>"]}, {"ikon": "🧩", "titel": "Vad modellen kan och inte kan", "text": ["<p>Med partikelmodellen kan du förklara varför en gas fyller hela rummet och varför en brustablett löser sig fortare i varmt vatten: partiklarna rör sig snabbare. Men modellen säger ingenting om ämnets färg eller lukt, och i bilden ser partiklarna ut som runda bollar, vilket är en förenkling. När vi frågar något som modellen inte kan svara på behöver vi en annan eller en bättre modell.</p>", "<p>Modeller finns överallt i vardagen: en karta, ett kretsschema, en molekylmodell av kulor och pinnar. Alla är förenklingar som är bra för ett visst syfte.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>En karta över Luleå är en modell. Vad kan du se på kartan, och vad kan du inte se? Vad skulle du behöva en annan modell för?</div>"], "fragor": [{"f": "Vad är en modell i kemi?", "svar": "En förenkling som hjälper oss att förklara och förutsäga något vi inte kan se eller mäta direkt."}, {"f": "Varför är en modell inte samma sak som verkligheten?", "svar": "Den lämnar medvetet bort detaljer. Den kan förklara vissa saker men inte allt."}, {"f": "Ge ett exempel på något en modell kan förklara och något den inte kan förklara.", "svar": "T.ex. partikelmodellen förklarar varför gas fyller hela rummet, men säger inget om ämnets färg."}, {"f": "Vad händer med en modell när nya undersökningar visar något den inte kan förklara?", "svar": "Modellen ändras eller byts ut mot en bättre."}]}], "begrepp": [{"term": "Begränsning", "forklaring": "Det en modell inte kan förklara."}, {"term": "Modell", "forklaring": "En förenkling som förklarar och förutsäger."}]}, "fordjupning": {"sektioner": [{"ikon": "🧩", "titel": "Vad är en modell i kemi?", "text": ["<p>I grundtexten lärde du dig att en modell är en förenkling. Men inte alla modeller är lika bra. Vad skiljer en användbar modell från en dålig?</p>", "<p><strong>En modell ska kunna förklara och förutsäga.</strong> Partikelmodellen förklarar att en gas fyller en behållare, och den förutsäger att gasen går att pressa ihop eftersom det är stora avstånd mellan partiklarna. Förutsägelser kan man pröva. Om en förutsägelse inte stämmer med mätningar måste modellen ändras eller bytas.</p>", "<p><strong>En modell passar ett syfte.</strong> Den bästa modellen är inte den mest detaljerade utan den som passar frågan. En tunnelbanekarta lämnar bort nästan allt, men fungerar utmärkt för att byta tåg. Den fungerar sämre om du vill veta avståndet i meter. På samma sätt är en enkel modell med runda partiklar bra för att förklara varför ämnen byter form, men den säger inget om hur en atom är uppbyggd.</p>", "<p><strong>En modell har gränser, och goda forskare säger vilka.</strong> Att veta var en modell slutar fungera är lika viktigt som att veta vad den kan.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Ge ett exempel på en modell som är bra för ett syfte men dålig för ett annat. Förklara varför.</div>"]}, {"ikon": "✏️", "titel": "Modeller prövas, de bevisas inte", "text": ["<p>En modell kan ha stöd av många undersökningar, men den kan inte bevisas för alltid. Nästa undersökning kan visa något den inte förklarar. Därför säger forskare hellre att en modell har starkt stöd än att den är ”bevisad”. Det är ingen svaghet: det är så vetenskap förbättras.</p>"]}], "begrepp": [{"term": "Begränsning", "forklaring": "Något modellen inte kan förklara eller en situation där den inte gäller."}, {"term": "Förutsägelse", "forklaring": "Det en modell säger ska hända, som man kan pröva."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-1-2-2"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Hur kemin vuxit fram", "text": ["<p>För länge sedan trodde man att allt var gjort av fyra element: jord, vatten, luft och eld. Det trodde man i över 2 000 år.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_tidslinje.png\" alt=\"\"></figure>", "<p>Boyle tvivlade 1661. Han ville ha bevis från försök.</p>", "<p>Lavoisier vägde ämnen 1789. Han visade att massan är lika stor före och efter en reaktion.</p>", "<p>Dalton föreslog 1808 att allt är gjort av atomer. Atomer av olika ämnen väger olika.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_massa.png\" alt=\"\"></figure>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Modeller ändras när nya undersökningar visar något nytt: fyra element blev atomer.</div>"]}, {"ikon": "✏️", "titel": "Öva: Hur kemin vuxit fram", "text": [], "ovningar": [{"typ": "streck", "fraga": "Dra streck till rätt forskare.", "vanster": ["Boyle", "Lavoisier", "Dalton"], "hoger": ["atomteori", "krävde bevis från försök", "massan bevaras"], "ratt": ["krävde bevis från försök", "massan bevaras", "atomteori"]}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Man trodde länge att allt var fyra element.", "Lavoisier vägde ämnen.", "Atomteorin kom före Boyle."], "ratt": [true, true, false]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["atomer", "försök", "massan"], "meningar": ["Boyle ville ha bevis från §.", "Lavoisier visade att § bevaras.", "Dalton sa att allt består av §."], "ratt": ["försök", "massan", "atomer"]}, {"typ": "skriv", "fraga": "Varför är det bra att en modell kan ändras?", "borja": "Det är bra eftersom", "forslag": "Man kan rätta fel och förbättra förklaringarna när man får nya belägg."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Hur kemin vuxit fram", "text": ["<p>Kemisk kunskap har vuxit fram under tusentals år. De första förklaringarna kom från filosofer som tänkte ut hur världen fungerar. Den grekiske filosofen <strong>Empedokles</strong> (ca 450 f.Kr.) menade att allt är uppbyggt av fyra ”rötter”: jord, vatten, luft och eld. <strong>Aristoteles</strong> (ca 350 f.Kr.) byggde ut läran om de fyra elementen, och den levde kvar i över tvåtusen år.</p>", "<p>Under medeltiden försökte alkemister bland annat göra guld av andra ämnen. De lyckades inte, men de utvecklade många arbetssätt och redskap som kemin senare använde.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_tidslinje.png\" alt=\"Bild 1.7 Fem steg i kemins historia, från Empedokles till Dalton.\"><figcaption><strong>Bild 1.7</strong> Fem steg i kemins historia, från Empedokles till Dalton.</figcaption></figure>"]}, {"ikon": "🔎", "titel": "Från tro till försök", "text": ["<p>År 1661 gav den engelske forskaren <strong>Robert Boyle</strong> ut boken <em>The Sceptical Chymist</em>. Han tvivlade på de fyra elementen och krävde att påståenden skulle prövas med försök. Det var ett viktigt steg mot kemi som experimentell vetenskap.</p>", "<p>Fransmannen <strong>Antoine Lavoisier</strong> använde noggranna vågar. År 1789 beskrev han att massan är lika stor före och efter en reaktion i ett slutet kärl: ingenting försvinner, ämnena bara ändrar form. Han gav också syre dess namn. Du ser tanken i bild 1.8: en sluten flaska med en tablett och vatten väger lika mycket före och efter reaktionen, eftersom gasen blir kvar i flaskan.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_massa.png\" alt=\"Bild 1.8 Massan är lika före och efter reaktionen när inget släpper ut ur flaskan.\"><figcaption><strong>Bild 1.8</strong> Massan är lika före och efter reaktionen när inget släpper ut ur flaskan.</figcaption></figure>", "<p>Engelsmannen <strong>John Dalton</strong> kom 1808 med en <strong>atomteori</strong>. Han föreslog att varje grundämne består av små atomer som är lika varandra och väger lika mycket, och att atomer av olika ämnen väger olika. Han menade att föreningar bildas när atomer sätts ihop i enkla förhållanden, till exempel en kolatom och en syreatom i kolmonoxid. Atomerna skapas inte och försvinner inte i en reaktion. Det passade med Lavoisiers vägningar.</p>", "<p>Daltons teori är en modell. Idag vet vi mer: atomerna består själva av ännu mindre delar. Men grundtanken att allt är uppbyggt av atomer lever kvar.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_dalton.png\" alt=\"Bild 1.9 Två av Daltons idéer: atomer av olika ämnen väger olika, och föreningar bildas i enkla förhållanden.\"><figcaption><strong>Bild 1.9</strong> Två av Daltons idéer: atomer av olika ämnen väger olika, och föreningar bildas i enkla förhållanden.</figcaption></figure>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Läran om fyra element levde över 2 000 år. Vad fick till slut forskarna att byta modell? Varför är det bra att en modell kan bytas ut?</div>"], "fragor": [{"f": "Vad ansåg Empedokles och Aristoteles att allt var uppbyggt av?", "svar": "Fyra element (jord, vatten, luft och eld)."}, {"f": "Vad gjorde Boyle annorlunda?", "svar": "Han tvivlade på de fyra elementen och krävde att påståenden skulle prövas med försök."}, {"f": "Vad visade Lavoisier med sina vägningar?", "svar": "Att massan är lika stor före och efter en reaktion: ingenting försvinner."}, {"f": "Vad säger Daltons atomteori om grundämnen?", "svar": "Att ett grundämne består av atomer som är lika varandra och väger lika mycket, och att olika grundämnen har olika atomer."}, {"f": "Varför är det en styrka att modeller kan ändras?", "svar": "Man kan rätta fel och förbättra förklaringarna när nya undersökningar visar mer."}]}], "begrepp": [{"term": "Atom", "forklaring": "Den minsta delen av ett grundämne som behåller grundämnets egenskaper."}, {"term": "Grundämne", "forklaring": "Ämne som inte går att dela upp i enklare ämnen med kemiska metoder."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Hur kemin vuxit fram", "text": ["<p>När John Dalton 1808 lade fram sin atomteori byggde den på tydliga idéer. Genom att jämföra dem med vad vi vet i dag kan du se hur en modell kan vara både användbar och ofullständig.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/f_dalton_nu.png\" alt=\"Bild F1.3 Daltons atom som en hård, odelbar kula, och en senare modell där atomen har en kärna och elektroner.\"><figcaption><strong>Bild F1.3</strong> Daltons atom som en hård, odelbar kula, och en senare modell där atomen har en kärna och elektroner.</figcaption></figure>", "<p><strong>Vad höll?</strong> Daltons idé att ämnen består av atomer, att atomer av olika grundämnen skiljer sig åt och att atomer inte skapas eller förstörs i en kemisk reaktion stämmer fortfarande bra. Den förklarar Lavoisiers observation att massan bevaras: om inga atomer försvinner kan inte massan minska. Den förklarar också att ämnen ofta bildas i enkla förhållanden, till exempel en kolatom med en eller två syreatomer.</p>", "<p><strong>Vad ändrades?</strong> Dalton tänkte sig atomen som en hård, odelbar kula. Senare undersökningar visade att atomer har delar: en kärna och elektroner. Daltons tanke att alla atomer av samma grundämne är exakt likadana och väger lika mycket behövde också justeras. Det finns atomer av samma ämne som väger olika (isotoper).</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Var Dalton ”fel”? Resonera: vad var rätt, vad var förenklat och varför fortsätter man ändå att undervisa om hans idéer?</div>"]}, {"ikon": "📖", "titel": "Varför blev det ett byte, och varför tog det tid?", "text": ["<p>Läran om fyra element levde i över 2 000 år. Det beror delvis på att den passade vardagliga iakttagelser: trä som brinner verkar släppa ut eld, och vatten som kokar verkar bli luft. Man vägde sällan, så få såg att något inte stämde. Det var när Boyle krävde försök och Lavoisier vägde som modellen började få problem. Dalton gav en ny modell som stämde med mätningarna. Så fungerar modellbyten: de sker inte för att någon tycker annorlunda, utan för att undersökningar visar något som den gamla modellen inte klarar.</p>"]}], "begrepp": [{"term": "Elektron", "forklaring": "En liten, negativt laddad del som finns i atomer."}, {"term": "Isotoper", "forklaring": "Atomer av samma grundämne som väger olika."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-1-2-3"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Granska kemipåståenden", "text": ["<p>Du ser påståenden om kemi i reklam: ”Kemikaliefritt!” eller ”100 % naturligt!”. Stämmer de?</p>", "<p>Ställ frågor. Det kallas <strong>källkritik</strong>.</p>", "<ol><li>Vem säger det?</li><li>Varför säger de det? Vill de sälja?</li><li>Vilka belägg finns?</li><li>Hur gammal är informationen?</li><li>Vad säger andra källor?</li></ol>", "<p><strong>Kemikalie</strong> betyder kemiskt ämne. Vatten och salt är kemikalier. Därför kan inget vara kemikaliefritt.</p>", "<p>Naturligt betyder inte ofarligt. Flugsvampen är naturlig men giftig.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Fråga: vem, varför, vilka belägg? Naturligt är inte alltid ofarligt.</div>"]}, {"ikon": "✏️", "titel": "Öva: Granska kemipåståenden", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vilken fråga är bra när du granskar en reklam?", "val": ["Vill de sälja något?", "Vilken färg har förpackningen?", "Hur stor är bilden?"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Vatten är en kemikalie.", "Allt som är naturligt är ofarligt.", "Reklam vill ofta sälja något."], "ratt": [true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["belägg", "kemikalie", "källkritik"], "meningar": ["Att ställa frågor om en källa kallas §.", "Mätningar som visar att något stämmer är §.", "Vatten är en §."], "ratt": ["källkritik", "belägg", "kemikalie"]}, {"typ": "skriv", "fraga": "Skriv en fråga du skulle ställa om en reklam som säger ”kemikaliefri”.", "borja": "Jag skulle fråga", "forslag": "Till exempel: Vilka ämnen innehåller den, och vilka belägg finns?"}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Granska kemipåståenden", "text": ["<p>Du möter påståenden om kemi hela tiden: ”Ny fläckborttagare – tar bort allt!”, ”Kemikaliefritt”, ”100 % naturligt”. Några stämmer, andra är reklam eller halvsanningar. Därför behöver du kunna <strong>granska</strong> dem, och här är <strong>källkritik</strong> ett verktyg.</p>", "<ol><li><strong>Vem</strong> säger det? Är det en forskare, en myndighet, ett företag eller en privatperson?</li><li><strong>Varför</strong> säger de det? Vill de informera, övertyga eller sälja?</li><li><strong>Vilka belägg</strong> finns? Hänvisar de till mätningar eller undersökningar du kan se?</li><li><strong>Hur gammal</strong> är informationen? Har kunskapen ändrats?</li><li><strong>Vad säger andra källor?</strong> Finns det oberoende källor som säger samma sak?</li></ol>"]}, {"ikon": "📖", "titel": "”Kemikaliefritt” och ”naturligt”", "text": ["<p>Ordet <strong>kemikalie</strong> betyder egentligen kemiskt ämne. Vatten, salt, socker och syre är alla kemikalier. Därför kan ingenting vara bokstavligen ”kemikaliefritt”. Ordet används ofta för att säga ”utan ämnen jag tycker är farliga”, men det säger inget om vilka ämnen det gäller eller hur farliga de är.</p>", "<p>”Naturligt” betyder inte heller ofarligt. Flugsvampen är naturlig men giftig. Om något är farligt beror på vilket ämne det är och hur mycket man får i sig, inte på om det kommer från naturen eller en fabrik.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Du ser en annons: ”Vår tvål är kemikaliefri och därför helt ofarlig.” Vilka frågor ställer du?</div>"]}, {"ikon": "✏️", "titel": "Vad går att pröva?", "text": ["<p>Vissa påståenden går att pröva själv med ett rättvist försök. ”Fläckborttagare X tar bort fläckar bättre än vanligt diskmedel” kan du undersöka: du väljer en fläck, använder samma mängd, samma tid och en jämförelse med bara vatten. Andra påståenden, som ”den är bäst”, går inte att pröva eftersom det inte är tydligt vad ”bäst” betyder. En bra granskare frågar alltid: <em>Går det här att mäta, och vem har mätt?</em></p>"], "fragor": [{"f": "Vilka frågor ställer du för att granska ett påstående?", "svar": "Vem säger det, varför, vilka belägg finns, hur gammalt är det och säger andra källor samma sak?"}, {"f": "Varför är ordet ”kemikaliefri” missvisande?", "svar": "Allt är gjort av kemiska ämnen, även vatten och luft. Ordet säger inte något om hur farlig produkten är."}, {"f": "Är allt som är naturligt ofarligt? Motivera.", "svar": "Nej. Naturliga ämnen kan vara giftiga, t.ex. gift i flugsvamp. Om något är farligt beror på ämnet och mängden, inte på om det är naturligt."}, {"f": "Varför är en reklam inte en tillräcklig källa för att veta om en produkt fungerar?", "svar": "Avsändaren vill sälja och väljer vad som visas. Man behöver oberoende belägg eller ett eget rättvist test."}]}], "begrepp": [{"term": "Belägg", "forklaring": "Mätningar eller undersökningar som stöder ett påstående."}, {"term": "Källkritik", "forklaring": "Att granska vem som säger något, varför och med vilka belägg."}, {"term": "Påstående", "forklaring": "Något som sägs vara sant."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Granska kemipåståenden", "text": ["<p>I grundtexten fick du fem frågor att ställa till en källa. Här skärper vi granskningen: vad är det som ofta går snett i påståenden om kemi?</p>", "<p><strong>Saknad jämförelse.</strong> ”98 procent av 50 testpersoner var nöjda med vår fläckborttagare.” Nöjda jämfört med vad? Utan jämförelse med bara vatten eller en annan produkt går det inte att veta om resultatet beror på produkten. Det är samma skäl som i ditt eget labb: du behöver en jämförelse.</p>", "<p><strong>Orsak och samband.</strong> Att två saker hänger ihop betyder inte att den ena orsakar den andra. Om fler glassar säljs när fler badar är det inte glassen som orsakar badandet. Båda beror på varmt väder.</p>", "<p><strong>Få mätningar eller utvalda resultat.</strong> Att visa bara de bästa resultaten, eller välja en jämförelse som ser bäst ut, ger en missvisande bild. Fråga: hur många mätningar, och hur valdes de?</p>", "<p><strong>Otydliga ord.</strong> ”Kemikaliefri”, ”naturlig” och ”giftfri” betyder olika saker för olika personer. Allt är kemiska ämnen, och naturliga ämnen kan vara giftiga. Mer användbart är att fråga <em>vilka ämnen</em> det gäller, <em>hur mycket</em> och <em>vilken fara</em> de utgör.</p>", "<div class=\"ruta ruta-fakta\"><span class=\"ruta-rubrik\">Granska kritiskt</span>En annons säger: ”Vår tvål innehåller 100 % naturliga ingredienser och är därför snällare mot huden.” Vilka frågor ställer du? Vilka två saker blandas ihop i påståendet?</div>"]}, {"ikon": "📖", "titel": "Vad är ett bra belägg?", "text": ["<p>Ett bra belägg bygger på mätningar som någon annan kan upprepa, har en jämförelse, kommer från en källa utan egen vinning i frågan eller är kontrollerad av flera oberoende källor, och säger hur säkert resultatet är. Du kan inte alltid kontrollera allt själv, så du behöver också kunna bedöma <em>vem</em> du litar på och <em>varför</em>. Ett bra svar på frågan ”stämmer det?” är ofta ”det beror på vad som menas, och här är vad som är belagt”.</p>"]}], "begrepp": [{"term": "Orsak", "forklaring": "Det som gör att något händer."}, {"term": "Samband", "forklaring": "Två saker som ändras tillsammans. Det betyder inte att den ena orsakar den andra."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-1-2-l"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧪", "titel": "Labb 1.2 Fungerar fläckborttagaren?", "text": ["<p><strong>Fråga:</strong> Tar fläckborttagare X bort en fläck bättre än vatten, diskmedel och tvättmedel? (Namnet är påhittat.)</p>", "<p>Du behöver: fyra tygbitar med lika fläck, fyra glas, vätskorna, ur, skyddsglasögon och handskar.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_flack.png\" alt=\"\"></figure>", "<ol><li>Märk tygbitarna A–D.</li><li>Häll lika mycket av varje vätska i varsitt glas.</li><li>Lägg tygbitarna i vätskorna. Låt dem ligga lika länge.</li><li>Skölj lika länge och låt torka.</li><li>Sätt poäng: 0 = ingen skillnad, 3 = fläcken är borta. Låt en kamrat sätta poäng utan att veta vilken som är vilken.</li></ol>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Vätska</th><th>Poäng 0–3</th></tr><tr><td>A Bara vatten</td><td></td></tr><tr><td>B Diskmedel</td><td></td></tr><tr><td>C Fläckborttagare X</td><td></td></tr><tr><td>D Tvättmedel</td><td></td></tr></table></div>", "<p><strong>Säkerhet:</strong> Ha skyddsglasögon och handskar. Läs etiketten. Blanda aldrig produkter. Tvätta händerna.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Vatten är med som jämförelse. Ändra bara vätskan.</div>"]}, {"ikon": "✏️", "titel": "Öva: Labb 1.2 Fungerar fläckborttagaren?", "text": [], "ovningar": [{"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["jämförelse", "poäng", "vätskan"], "meningar": ["Jag ändrade §.", "Jag satte § på fläcken.", "Bara vatten är en §."], "ratt": ["vätskan", "poäng", "jämförelse"]}, {"typ": "skriv", "fraga": "Tog fläckborttagare X bort fläcken bäst? Skriv vad du såg.", "borja": "Jag såg att", "forslag": "Egna resultat."}, {"typ": "skriv", "fraga": "Vad testade du inte? Till exempel andra sorters fläckar.", "borja": "Jag testade inte", "forslag": "Egna svar, till exempel andra sorters fläckar eller tyger."}]}]}, "vanlig": {"sektioner": [{"ikon": "🧪", "titel": "Labb 1.2 Fungerar fläckborttagaren?", "text": ["<p>En reklam påstår att ”Fläckborttagare X” tar bort fläckar bättre än andra produkter. Du ska planera och genomföra ett rättvist test av påståendet. Produktnamnet är påhittat.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade1/v_flack.png\" alt=\"Bild 1.10 Fyra tygbitar med likadan fläck och fyra vätskor: A bara vatten (jämförelse), B diskmedel, C fläckborttagare X och D tvättmedel.\"><figcaption><strong>Bild 1.10</strong> Fyra tygbitar med likadan fläck och fyra vätskor: A bara vatten (jämförelse), B diskmedel, C fläckborttagare X och D tvättmedel.</figcaption></figure>", "<p><strong>Frågeställning:</strong> Tar fläckborttagare X bort en fläck bättre än bara vatten, diskmedel och tvättmedel?</p>", "<p><strong>Hypotes:</strong> Skriv vilken du tror är bäst och varför.</p>", "<p><strong>Material:</strong> fyra likadana tygbitar (vit bomull) med samma fläck (till exempel te eller kaffe som fått torka), fyra glas, mätcylinder, de fyra vätskorna, sked eller pinne, ur, skyddsglasögon, handskar och en referensskala (se nedan).</p>"]}, {"ikon": "📖", "titel": "Planera och gör så här", "text": ["<ol><li>Bestäm vad du ändrar (vätskan), vad du mäter (hur ljus fläcken blir) och vad du håller lika: fläckens storlek, mängden vätska, tiden och hur du rör.</li><li>Gör fläckarna likadana och låt dem torka. Märk tygbitarna A–D.</li><li>Häll samma mängd av varje vätska i varsitt glas. Lägg tygbitarna i vätskorna och låt dem ligga lika länge. Rör lika mycket.</li><li>Skölj lika länge och låt torka. Jämför mot en referensskala: 0 = ingen skillnad, 1 = lite ljusare, 2 = mycket ljusare, 3 = fläcken är borta.</li><li>Låt en kamrat som inte vet vilken som är vilken sätta poäng. Då påverkar förväntningarna inte resultatet.</li><li>Gör om försöket minst en gång. Skriv resultatet i tabellen.</li></ol>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Bra att veta</span>Läs etiketten på produkterna innan du börjar. Blanda aldrig olika rengöringsmedel med varandra.</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Vätska</th><th>Poäng försök 1</th><th>Poäng försök 2</th><th>Medelvärde</th></tr><tr><td>A Bara vatten</td><td></td><td></td><td></td></tr><tr><td>B Diskmedel</td><td></td><td></td><td></td></tr><tr><td>C Fläckborttagare X</td><td></td><td></td><td></td></tr><tr><td>D Tvättmedel</td><td></td><td></td><td></td></tr></table></div>"]}, {"ikon": "❓", "titel": "Frågor", "text": ["<ol><li>Vilken vätska tog bort fläcken bäst? Stämmer det med reklamens påstående?</li><li>Varför är det bra med en jämförelse med bara vatten och en kamrat som sätter poäng?</li><li>Vilka felkällor kan ha påverkat? Hur kan du minska dem?</li><li>Vad kan du säga och inte säga om fläckborttagare X utifrån just ditt test? Vilka fläckar och tyger testade du inte?</li></ol>", "<p class=\"not\">Säkerhet: Använd skyddsglasögon och handskar. Läs etiketten. Blanda aldrig produkter. Drick inte och undvik att andas in ångor; vädra. Tvätta händerna efteråt.</p>"]}], "begrepp": [{"term": "Belägg", "forklaring": "Resultat som stöder eller motsäger ett påstående."}, {"term": "Jämförelse", "forklaring": "Ett prov utan det du testar, här bara vatten."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-1-s"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📌", "titel": "Sammanfattning", "text": ["<p>Läs orden och titta på bilderna. Du kan komma tillbaka hit när du läser.</p>", "<p>Här är allt det viktigaste i kapitlet. Läs det en gång till.</p>", "<ul class=\"viktigast\"><li>Kemi är läran om ämnen och hur de förändras. Kemister undersöker och mäter.</li></ul>", "<ul class=\"viktigast\"><li>Använd skyddsglasögon, smaka aldrig och läs av mätcylindern rätt. Faropiktogram visar faror.</li></ul>", "<ul class=\"viktigast\"><li>En undersökning: fråga, hypotes, test och slutsats.</li></ul>", "<ul class=\"viktigast\"><li>Ett rättvist försök: ändra en sak, mät en sak och håll resten lika.</li></ul>", "<ul class=\"viktigast\"><li>Upprepa mätningarna, räkna medelvärde och skriv en slutsats som svarar på frågan.</li></ul>", "<ul class=\"viktigast\"><li>En modell är en förenkling. Den kan förklara en del men inte allt, och den kan ändras.</li></ul>", "<ul class=\"viktigast\"><li>Från fyra element till atomer: Boyle, Lavoisier och Dalton.</li></ul>", "<ul class=\"viktigast\"><li>Granska påståenden: vem, varför, vilka belägg? Allt är kemikalier.</li></ul>"]}], "begrepp": [{"term": "atom", "forklaring": "den minsta delen av ett grundämne"}, {"term": "belägg", "forklaring": "mätningar som visar att något stämmer"}, {"term": "faropiktogram", "forklaring": "en symbol som visar vilken fara ett ämne har"}, {"term": "felkälla", "forklaring": "något som kan göra mätningen osäker"}, {"term": "grundämne", "forklaring": "ett ämne som inte går att dela upp i enklare ämnen"}, {"term": "hypotes", "forklaring": "en gissning som man kan pröva"}, {"term": "kemi", "forklaring": "läran om ämnen och hur de förändras"}, {"term": "kemikalie", "forklaring": "ett kemiskt ämne, till exempel vatten eller salt"}, {"term": "källkritik", "forklaring": "att kolla vem som säger något och varför"}, {"term": "medelvärde", "forklaring": "lägg ihop alla värden och dela med antalet"}, {"term": "menisk", "forklaring": "vattenytans böjning i mätcylindern"}, {"term": "modell", "forklaring": "en enkel bild eller idé som förklarar något"}, {"term": "mätcylinder", "forklaring": "ett glasrör med skala för att mäta volym"}, {"term": "naturvetenskap", "forklaring": "kunskap som man prövar med undersökningar"}, {"term": "partikel", "forklaring": "en mycket liten bit som ämnen är uppbyggda av"}, {"term": "rättvist försök", "forklaring": "du ändrar bara en sak i taget"}, {"term": "signalord", "forklaring": "Fara eller Varning på en etikett"}, {"term": "slutsats", "forklaring": "svaret på frågan, byggt på resultatet"}, {"term": "variabel", "forklaring": "något som kan ändras eller mätas i ett försök"}, {"term": "ämne", "forklaring": "en sorts material, till exempel vatten eller socker"}]}, "vanlig": {"sektioner": [{"ikon": "📌", "titel": "Sammanfattning", "text": ["<ul><li><strong>Kemi</strong> är läran om ämnen och hur de förändras. Kemi är en naturvetenskap: svaren prövas med undersökningar och mätningar.</li><li>I kemilabbet använder du skyddsglasögon, sätter upp långt hår, smakar aldrig på något och följer instruktionen. <strong>Faropiktogram</strong> och etiketter berättar om farorna.</li><li>Du läser av en mätcylinder med ögonen i nivå med ytan, vid den lägsta delen av <strong>menisken</strong>.</li><li>En <strong>hypotes</strong> är en gissning som går att pröva. I ett <strong>rättvist försök</strong> ändrar du en <strong>oberoende variabel</strong>, mäter en <strong>beroende variabel</strong> och håller övriga <strong>kontrollerade</strong>.</li><li>Du upprepar mätningar, räknar <strong>medelvärde</strong>, redovisar i tabell och diagram med enheter och värderar <strong>felkällor</strong> innan du drar en <strong>slutsats</strong>.</li><li>I brustablettförsöket gick det fortare ju varmare vattnet var. Det kan förklaras med att partiklarna rör sig snabbare.</li><li>En <strong>modell</strong> är en förenkling som förklarar och förutsäger. Den har <strong>begränsningar</strong> och kan ändras när nya undersökningar visar mer.</li><li>Läran om fyra element ersattes steg för steg: Boyle krävde försök, Lavoisier visade att massan bevaras och Dalton föreslog en <strong>atomteori</strong>.</li><li>Med <strong>källkritik</strong> frågar du vem som säger något, varför, vilka belägg som finns, hur gammalt det är och vad andra källor säger.</li><li><strong>Kemikalie</strong> betyder kemiskt ämne. ”Kemikaliefritt” och ”naturligt” säger inte om något är farligt eller ofarligt.</li></ul>"]}], "begrepp": [{"term": "Atom", "forklaring": "Den minsta delen av ett grundämne som behåller grundämnets egenskaper."}, {"term": "Atomteori", "forklaring": "Daltons idé från 1808 att allt består av atomer."}, {"term": "Belägg", "forklaring": "Mätningar eller undersökningar som stöder ett påstående."}, {"term": "Beroende variabel", "forklaring": "Det du mäter i ett försök."}, {"term": "Faropiktogram", "forklaring": "Symbol i röd ruta på spetsen som visar vilken fara ett ämne har."}, {"term": "Felkälla", "forklaring": "Något som gör en mätning mindre säker."}, {"term": "Grundämne", "forklaring": "Ämne som inte går att dela upp i enklare ämnen med kemiska metoder."}, {"term": "Hypotes", "forklaring": "En gissning som går att pröva."}, {"term": "Kemi", "forklaring": "Läran om ämnen och hur de förändras."}, {"term": "Kemikalie", "forklaring": "Kemiskt ämne, t.ex. vatten eller salt."}, {"term": "Kontrollerad variabel", "forklaring": "Något du håller lika i ett försök."}, {"term": "Källkritik", "forklaring": "Att granska vem som säger något, varför och med vilka belägg."}, {"term": "Medelvärde", "forklaring": "Summan av värdena delat med antalet."}, {"term": "Menisk", "forklaring": "Vätskeytans böjning i en mätcylinder."}, {"term": "Modell", "forklaring": "En förenkling som förklarar och förutsäger."}, {"term": "Oberoende variabel", "forklaring": "Det du ändrar i ett försök."}, {"term": "Partikelmodell", "forklaring": "Modell där ämnen är uppbyggda av små partiklar."}, {"term": "Rättvist försök", "forklaring": "Försök där bara en variabel ändras i taget."}, {"term": "Signalord", "forklaring": "Fara eller Varning på en etikett."}, {"term": "Slutsats", "forklaring": "Svaret på frågan, byggt på resultatet."}, {"term": "Undersökningsbar fråga", "forklaring": "Fråga som går att svara på med mätningar."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-1-t"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📝", "titel": "Testa dig själv", "text": ["Nu får du visa vad du har lärt dig. Du kan titta i kapitlet om du vill."], "ovningar": [{"typ": "ringa", "fraga": "Vad ska du ha på dig i ett kemilabb?", "val": ["Skyddsglasögon", "Solglasögon", "Hörlurar"], "ratt": 0}, {"typ": "streck", "fraga": "Dra streck till rätt förklaring.", "vanster": ["Hypotes", "Medelvärde", "Modell", "Källkritik"], "hoger": ["att granska vem som säger något", "en enkel idé som förklarar något", "en gissning som går att pröva", "summan delat med antalet"], "ratt": ["en gissning som går att pröva", "summan delat med antalet", "en enkel idé som förklarar något", "att granska vem som säger något"]}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Man ska ändra en sak i taget.", "Man behöver bara mäta en gång.", "Allt är kemikalier.", "Naturligt är alltid ofarligt.", "Modeller kan ändras.", "Lavoisier visade att massan bevaras."], "ratt": [true, false, true, false, true, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["atomer", "felkälla", "hypotes"], "meningar": ["En gissning som går att pröva är en §.", "Något som gör en mätning osäker är en §.", "Dalton sa att allt består av §."], "ratt": ["hypotes", "felkälla", "atomer"]}, {"typ": "siffror", "fraga": "Sätt i ordning. Skriv 1, 2, 3 och 4.", "delar": ["Gör ett test", "Ställ en fråga", "Skriv en slutsats", "Skriv en hypotes"], "ratt": [3, 1, 4, 2]}, {"typ": "skriv", "fraga": "Varför ska man bara ändra en sak i taget?", "borja": "Man ska ändra en sak eftersom", "forslag": "Annars vet man inte vad som gav skillnaden."}, {"typ": "skriv", "fraga": "Räkna ut medelvärdet av 148 s, 160 s och 148 s. Avrunda till hela sekunder.", "borja": "Medelvärdet är", "forslag": "(148 + 160 + 148) ÷ 3 = 152 s."}, {"typ": "skriv", "fraga": "Varför kan man inte lita på en reklam utan att kolla?", "borja": "Det är så eftersom", "forslag": "Reklam vill ofta sälja något, så man behöver kolla belägg."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Del A · Välj ett alternativ", "text": ["Uppgifterna liknar uppgifterna på nationella prov i kemi. Personer, annonser och mätvärden är påhittade."], "ovningar": [{"typ": "ringa", "fraga": "Vad betyder faropiktogrammet med en människa som har ett stjärnformat märke på bröstet?", "val": ["Ämnet är brandfarligt.", "Ämnet kan vara hälsofarligt, till exempel skada organ eller arvsmassan.", "Ämnet är bra för kroppen.", "Ämnet är en gas under tryck."], "ratt": 1}, {"typ": "ringa", "fraga": "Hur läser du av en mätcylinder rätt?", "val": ["Med ögonen ovanför ytan och vid ytans övre kant.", "Med ögonen i nivå med ytan och vid den lägsta delen av ytan.", "Med ögonen under ytan.", "Det spelar ingen roll."], "ratt": 1}, {"typ": "ringa", "fraga": "I ett försök undersöks hur mängden socker påverkar hur sött te smakar. Vilken är den oberoende variabeln?", "val": ["Hur sött teet smakar.", "Mängden socker.", "Mängden te.", "Temperaturen på teet."], "ratt": 1}, {"typ": "ringa", "fraga": "Vem krävde 1661 att påståenden om kemi skulle prövas med försök?", "val": ["Empedokles", "Aristoteles", "Boyle", "Dalton"], "ratt": 2}]}, {"ikon": "📖", "titel": "Del B · Svara kort", "text": [], "ovningar": [{"typ": "fri", "fraga": "Nämn två regler du alltid följer i ett kemilabb.", "forslag": "T.ex. använd skyddsglasögon, sätt upp långt hår, smaka aldrig på något, ät inte i labbet, följ instruktionen, torka upp spill, tvätta händerna."}, {"typ": "fri", "fraga": "Förklara vad en modell är i kemi.", "forslag": "En förenkling som hjälper oss att förklara och förutsäga något, till exempel något vi inte kan se. Den är inte verkligheten och har begränsningar."}]}, {"ikon": "📖", "titel": "Del C · Tolka resultat och förklara", "text": [], "ovningar": [{"typ": "fri", "fraga": "Elin undersökte hur snabbt en sockerbit löses i 2 dl vatten av olika temperatur. Hon upprepade varje försök tre gånger. Resultaten är påhittade.<br><div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Temperatur</th><th>Försök 1 (s)</th><th>Försök 2 (s)</th><th>Försök 3 (s)</th></tr><tr><td>20 °C</td><td>140</td><td>152</td><td>146</td></tr><tr><td>50 °C</td><td>48</td><td>52</td><td>50</td></tr></table></div>a) Räkna ut medelvärdet av tiden för varje temperatur.<br>b) Förklara med partikelmodellen varför tiden skiljer sig mellan temperaturerna.", "forslag": "a) 20 °C: (140 + 152 + 146) / 3 = 146 s. 50 °C: (48 + 52 + 50) / 3 = 50 s. b) Vid högre temperatur rör sig partiklarna i vattnet snabbare, så de träffar sockerbiten oftare och hårdare och sockret lossnar fortare."}, {"typ": "fri", "fraga": "Mia testade tre fläckborttagare. Hon tog olika mycket av varje och lät dem verka olika länge. Förklara varför hennes jämförelse inte är rättvis och hur hon kan göra den rättvis.", "forslag": "Hon ändrar flera saker samtidigt (mängd och tid), så hon vet inte vad som gav skillnaden. Hon ska ändra bara produkten och hålla mängd, tid, fläck, tyg och sätt att skölja lika. Hon bör också ha en jämförelse med bara vatten."}]}, {"ikon": "📖", "titel": "Del D · Resonera och ta ställning", "text": [], "ovningar": [{"typ": "fri", "fraga": "En annons säger: ”Vår kemikaliefria rengöring är säkrare än allt annat.” Granska påståendet. Förklara vad som är problemet med ordet ”kemikaliefri” och vilka frågor du skulle ställa för att avgöra om annonsen går att lita på.", "forslag": "Öppet svar. Ett välutvecklat svar förklarar att allt är kemiska ämnen, även vatten, så ”kemikaliefri” inte kan stämma bokstavligt och inte säger hur farliga ämnena är. Frågor: vem säger det, varför (sälja?), vilka belägg och mätningar finns, vad menas med ”säkrare”, jämfört med vad, vad säger oberoende källor, och vilken märkning (piktogram, faroangivelser) har produkten."}, {"typ": "fri", "fraga": "Läran om de fyra elementen levde i över 2 000 år innan den ersattes. Förklara varför det är en styrka för naturvetenskapen att modeller kan ändras. Använd ett exempel från kapitlet.", "forslag": "Öppet svar. Exempel: de fyra elementen byttes ut när Boyle krävde försök och Lavoisier och Dalton lade fram nya förklaringar som stämde bättre med mätningar. Att kunna ändra modellen gör att fel rättas och förklaringarna blir bättre. En vetenskap som aldrig ändrar sig kan inte lära sig något nytt."}]}, {"ikon": "📖", "titel": "Del E · Planera och resonera", "text": [], "ovningar": [{"typ": "fri", "fraga": "Elias tror att en brustablett löser sig fortare om man rör om i vattnet. Planera en undersökning som kan pröva hans idé. Beskriv hypotes, vad du ändrar, vad du mäter, vad du håller lika, hur du upprepar mätningarna och hur du dokumenterar resultatet.", "forslag": "Hypotes, t.ex. ”Om man rör om löser tabletten sig fortare, eftersom vattnet nära tabletten byts ut.” Ändra: omrörning (med/utan). Mäta: tid tills tabletten är upplöst. Hålla lika: vattenmängd, temperatur, tablettsort och storlek, glas, sättet att mäta tid. Upprepa minst tre gånger för varje fall och räkna medelvärde. Dokumentera i tabell med enheter och gärna diagram, samt felkällor."}, {"typ": "fri", "fraga": "En grupp mätte hur lång tid en brustablett tog att lösa sig (påhittade medelvärden): 10 °C: 132 s, 20 °C: 80 s, 30 °C: 52 s, 40 °C: 33 s, 50 °C: 22 s. Vilken tid skulle du uppskatta vid 35 °C? Förklara hur du kommer fram till det. Förklara också varför du inte kan vara säker på ett värde som ligger utanför det som är uppmätt, till exempel vid 80 °C.", "forslag": "Vid 35 °C ligger tiden mellan värdena vid 30 °C (ca 52 s) och 40 °C (ca 33 s), så ca 40–45 s. Kurvan sjunker mindre brant efter hand, så en rak linje mellan punkterna är en grov uppskattning. Vid 80 °C vet vi inte hur kurvan fortsätter eftersom inget är mätt där, och trenden kan ändras. Man kan inte vara säker utanför det uppmätta området."}]}]}, "fordjupning": {"sektioner": [{"ikon": "💭", "titel": "Resonera och ta ställning", "text": ["Uppgifterna liknar de svåraste uppgifterna på nationella prov. Personer, rubriker och mätvärden är påhittade. Svara utförligt och resonera i flera led."], "ovningar": [{"typ": "fri", "fraga": "Tre grupper mäter hur lång tid en brustablett tar att lösa sig vid 30 °C: 52 s, 49 s och 51 s. Gruppernas termometer visar dock 2 °C för mycket. a) Är det ett slumpfel eller ett systematiskt fel? b) Hur påverkar det precisionen och riktigheten? c) Hur kan de upptäcka felet och rätta till det?", "forslag": "a) Systematiskt fel: det är lika fel varje gång, och går åt samma håll. b) Precisionen blir bra (värdena ligger nära varandra, 52, 49, 51) men riktigheten dålig eftersom alla mätningar sker vid fel temperatur. c) Jämföra med en annan termometer eller med en känd temperatur, t.ex. isvatten (0 °C), och justera eller räkna om."}, {"typ": "fri", "fraga": "Klass 8B fick 70 s, 118 s och 72 s vid 20 °C. En elev vill stryka 118 s eftersom ”det är fel”. a) Förklara varför det inte är hederligt att bara stryka värdet. b) Beskriv vad man bör göra i stället. c) Räkna ut medelvärdet med och utan värdet och förklara vad du ska redovisa.", "forslag": "a) Värdet kan vara ett misstag, men det kan också vara en riktig mätning. Man får inte välja bort data bara för att den inte passar. b) Kontrollera anteckningar om en känd orsak, gör om mätningen om det går och redovisa öppet vad man gjort. c) Med: (70 + 118 + 72) / 3 = 87 s. Utan: (70 + 72) / 2 = 71 s. Redovisa båda, och motivera valet. Medianen är 72 s."}, {"typ": "fri", "fraga": "Elin säger: ”Mina mätningar visar att brustabletten löser sig dubbelt så fort vid 80 °C som vid 40 °C.” Hon har bara mätt vid 5, 20 och 40 °C. a) Förklara vad som är problemet. b) Vad kan hon säga med säkerhet, och vad är bara en gissning? c) Planera en mätning som kan pröva om tiden fortsätter minska när vattnet blir varmare (använd högst 60 °C av säkerhetsskäl) och beskriv hur du gör den säker att lita på.", "forslag": "a) Hon har inte mätt vid 80 °C, så det är en extrapolation utanför det uppmätta området. Kurvan kan ändra form, och vid mycket varmt vatten kan andra saker hända. b) Säkert: tiden minskade mellan 5, 20 och 40 °C. Gissning: vad som händer vid 80 °C. c) Mät vid fler temperaturer upp till högst 60 °C (av säkerhetsskäl, inte kokhett vatten), upprepa tre gånger vid varje, ha samma vattenmängd och tablettsort och redovisa medelvärde och spridning. Då ser man om kurvan fortsätter sjunka eller planar ut."}, {"typ": "fri", "fraga": "En lärare säger: ”Partikelmodellen är bra, men den är inte hela sanningen.” a) Förklara vad hon kan mena. b) Ge ett exempel på något modellen förklarar och ett exempel på något den inte säger. c) Förklara varför man ändå använder modellen.", "forslag": "a) Modellen är en förenkling: den förklarar mycket, men inte allt. b) Förklarar t.ex. att gas går att pressa ihop och att ämnen byter form. Säger inget om ämnets färg eller hur partiklarna är uppbyggda. c) Den är användbar för många syften, och enkla modeller är lättare att tänka med än mer detaljerade."}, {"typ": "fri", "fraga": "En elev påstår: ”Dalton hade fel, så hans atomteori är värdelös.” a) Förklara vad som stämde i teorin och vad som ändrats sedan dess. b) Förklara hur Lavoisiers vägningar stödde Daltons teori. c) Värdera elevens påstående.", "forslag": "a) Stämde: ämnen är uppbyggda av atomer, atomer av olika grundämnen skiljer sig åt och atomer skapas inte eller försvinner i reaktioner. Ändrades: atomer har delar (kärna och elektroner) och atomer av samma ämne kan väga olika (isotoper). b) Om atomer inte försvinner kan massan inte minska, vilket passar med att massan är lika före och efter. c) Påståendet är för svart-vitt. Teorin är förenklad men har varit grunden för modernare modeller. Modeller kan vara ofullständiga och ändå användbara."}, {"typ": "fri", "fraga": "En tillverkare skriver: ”Kemikaliefri rengöring. Testad: 9 av 10 nöjda!” a) Ge tre skäl till att vara skeptisk. b) Förklara skillnaden mellan samband och orsak med ett eget exempel. c) Planera ett test som kan pröva om rengöringen verkligen fungerar bättre än vanlig såpa, och beskriv hur du gör det rättvist.", "forslag": "a) T.ex. kemikaliefri säger inget (allt är kemikalier), ingen jämförelse, oklart vad 9 av 10 betyder (hur många, vilka, nöjda med vad), avsändaren vill sälja. b) Samband: att två saker ändras tillsammans. Orsak: att den ena gör att den andra händer. Exempel: glassförsäljning och badande, båda beror på varmt väder. c) Samma fläck, tyg, mängd och tid för båda produkterna och en jämförelse med bara vatten. Upprepa, låt någon som inte vet vilken som är vilken bedöma, redovisa med poäng och medelvärde."}]}]}}, nivaStandard: "vanlig"};
